<script setup lang="ts">import AdminLayout from '@/Layouts/AdminLayout.vue';import{Head,router,Link}from'@inertiajs/vue3';import{reactive}from'vue';const props=defineProps<{conversations:any,filters:any}>();const form=reactive({search:props.filters.search||'',type:props.filters.type||''});const filter=()=>router.get(route('admin.conversations.index'),form,{preserveState:true});</script>
<template><Head title="Conversations"/><AdminLayout><h1 class="text-2xl font-bold">Conversations</h1><p class="mt-1 text-sm text-slate-500">Metadata only. Private message content is available only while reviewing a report.</p><form class="mt-5 flex gap-3" @submit.prevent="filter"><input v-model="form.search" class="rounded border px-3 py-2" placeholder="ID, group, or participant"><select v-model="form.type" class="rounded border px-3 py-2"><option value="">All types</option><option value="private">Private</option><option value="group">Group</option></select><button class="rounded bg-slate-900 px-4 py-2 text-white">Filter</button></form><div class="mt-5 overflow-x-auto rounded-xl border bg-white"><table class="w-full text-sm"><thead class="bg-slate-50 text-left text-slate-500"><tr><th class="p-4">ID</th><th>Type</th><th>Participants / Name</th><th>Messages</th><th>Last activity</th></tr></thead><tbody><tr v-for="c in conversations.data" :key="c.id" class="border-t"><td class="p-4">#{{c.id}}</td><td class="capitalize">{{c.type}}</td><td>{{c.name || c.members.map((m:any)=>m.name).join(', ')}}</td><td>{{c.messages_count}}</td><td>{{new Date(c.updated_at).toLocaleString()}}</td></tr></tbody></table></div></AdminLayout></template>
